1	// The Deep Field sky: every person's card is a unique patch of space,
2	// minted deterministically from their identity. Same person, same sky,
3	// forever. Pure and dependency-free so it stays trivially testable.
4	
5	export type SkyStar = {
6	  x: number;
7	  y: number;
8	  r: number;
9	  hi: number; // resting opacity
10	  lo: number; // twinkle-low opacity
11	  dur: number; // twinkle duration seconds
12	  delay: number;
13	  rvd: number; // 0..1 reveal stagger seed: when this star ignites
14	  // Minors only: a seeded few keep their own twinkle; the rest render static
15	  // under a shared group shimmer, so the sky animates ~30 nodes, not ~150.
16	  featured?: boolean;
17	};
18	
19	export type SkyMajor = SkyStar & { hue: number };
20	
21	export type SkyData = {
22	  width: number;
23	  height: number;
24	  pad: number;
25	  hues: [number, number, number];
26	  nebulae: Array<{ cx: number; cy: number; rx: number; ry: number; hue: number; alpha: number }>;
27	  minors: SkyStar[];
28	  giants: SkyMajor[];
29	  majors: SkyMajor[];
30	  edges: Array<[number, number]>;
31	  flares: Array<{ x: number; y: number; len: number; dur: number; delay: number }>;
32	  shoot: { x1: number; y1: number; x2: number; y2: number; delay: number };
33	};
34	
35	const W = 384;
36	const H = 560;
37	const PAD = 34;
38	const MIN_SEPARATION = 68;
39	const MINOR_COUNT = 150;
40	// How many minors keep an individual twinkle. The rest go static under group
41	// shimmer -- see PersonSky. Fixed count so every sky animates the same handful.
42	const FEATURED_MINORS = 22;
43	
44	function hashString(s: string): number {
45	  let h = 2166136261;
46	  for (let i = 0; i < s.length; i++) {
47	    h ^= s.charCodeAt(i);
48	    h = Math.imul(h, 16777619);
49	  }
