node -e '
function lum(hex){const c=hex.replace("#","").match(/../g).map(h=>{let v=parseInt(h,16)/255;return v<=0.03928?v/12.92:Math.pow((v+0.055)/1.055,2.4);});return 0.2126*c[0]+0.7152*c[1]+0.0722*c[2];}
function cr(a,b){const l1=lum(a),l2=lum(b);return ((Math.max(l1,l2)+0.05)/(Math.min(l1,l2)+0.05)).toFixed(2);}
const L={ground:"#F6F5FA",raise:"#FFFFFF",ink:"#171A2B",muted:"#666C85",faint:"#9096AB",star:"#A9741B",unlit:"#A7ADC2"};
const D={ground:"#0B1020",raise:"#131B33",ink:"#E8E6F0",muted:"#868CA6",faint:"#575E7A",star:"#FFEBC7",unlit:"#55608A"};
console.log("LIGHT theme");
[["ink","ground"],["muted","ground"],["faint","ground"],["star","raise"],["unlit","raise"],["star","ground"]].forEach(([a,b])=>console.log("  "+a+" on "+b+": "+cr(L[a],L[b])));
console.log("DARK theme");
[["ink","ground"],["muted","ground"],["faint","ground"],["star","raise"],["unlit","raise"],["star","ground"]].forEach(([a,b])=>console.log("  "+a+" on "+b+": "+cr(D[a],D[b])));'

